  beginMatch(alphaCount=0,bravoCount=0){this.matchActive=true;this.player.health=100;this.player.alive=true;this.camera.position.set(0,1.68,15);this.yaw=0;this.pitch=0;this.camera.rotation.set(0,0,0);this.matchTime=0;this.bots.forEach(b=>this.scene.remove(b.group));this.bots=[];for(let i=0;i<alphaCount;i++)this.spawnBot('alpha',i);for(let i=0;i<bravoCount;i++)this.spawnBot('bravo',i);this.onEvent('matchStart',{bots:this.bots.length});}
  endMatch(){this.matchActive=false;document.exitPointerLock?.();}
  spawnBot(team,index){const g=new THREE.Group();const main=this.material(team==='alpha'?0x628f9a:0x9b5145),dark=this.material(0x252a26),skin=this.material(0x9e8a70);const torso=this.addBox(g,[0,1.12,0],[.66,.86,.38],main);this.addBox(g,[0,1.77,0],[.45,.42,.42],dark);const head=new THREE.Mesh(new THREE.SphereGeometry(.19,10,8),skin);head.position.y=2.08;head.castShadow=true;g.add(head);for(const x of [-.42,.42]){this.addBox(g,[x,.54,0],[.23,.8,.28],dark);this.addBox(g,[x,.98,-.25],[.18,.16,.56],dark);}this.addBox(g,[0,1.1,-.38],[.13,.12,.9],this.material(0x353c39,.4,.7));const angle=rand(0,Math.PI*2),dist=rand(18,50);g.position.set(Math.sin(angle)*dist,0,15-Math.cos(angle)*dist);this.scene.add(g);const bot={group:g,team,index,health:100,alive:true,fireAt:0,walk:rand(0,8),speed:rand(.8,1.25),goal:new THREE.Vector3(g.position.x+rand(-14,14),0,g.position.z+rand(-14,14))};this.bots.push(bot);}
  fire(){if(!this.matchActive||this.reloading||this.ammo[this.weapon]<=0){if(this.ammo[this.weapon]<=0)this.reload();return;}const now=performance.now();if(now-this.lastShot<(this.weapon===0?105:68))return;this.lastShot=now;this.ammo[this.weapon]--;this.onEvent('ammo',{ammo:this.ammo[this.weapon],reserve:this.reserve[this.weapon],weapon:this.weapon});this.weaponRoot.position.z=.04;setTimeout(()=>{if(this.weaponRoot)this.weaponRoot.position.z=0;},55);const ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(0,0),this.camera);ray.far=105;const candidates=this.bots.filter(b=>b.alive).map(b=>({bot:b,object:b.group.children[0]}));let hit=candidates.map(c=>({c,hit:ray.intersectObject(c.object,false)[0]})).filter(x=>x.hit).sort((a,b)=>a.hit.distance-b.hit.distance)[0];if(hit){hit.c.bot.health-=this.weapon===0?42:25;this.createHitEffect(hit.hit.point);if(hit.c.bot.health<=0)this.killBot(hit.c.bot);else this.onEvent('hit',{team:hit.c.bot.team});}else this.onEvent('shot');}
  createHitEffect(pos){const mat=new THREE.MeshBasicMaterial({color:0xe6bf78});const m=new THREE.Mesh(new THREE.SphereGeometry(.09,6,6),mat);m.position.copy(pos);this.scene.add(m);this.effects.push({mesh:m,life:.2});this.onEvent('hitmarker');}
  killBot(bot){bot.alive=false;bot.group.visible=false;this.onEvent('kill',{team:bot.team});}
  reload(){if(this.reloading||this.reserve[this.weapon]<=0||this.ammo[this.weapon]>=this.maxAmmo[this.weapon])return;this.reloading=true;this.onEvent('toast','RELOADING');setTimeout(()=>{const n=Math.min(this.maxAmmo[this.weapon]-this.ammo[this.weapon],this.reserve[this.weapon]);this.ammo[this.weapon]+=n;this.reserve[this.weapon]-=n;this.reloading=false;this.onEvent('ammo',{ammo:this.ammo[this.weapon],reserve:this.reserve[this.weapon],weapon:this.weapon});},this.weapon===0?1450:1250);}
  swapWeapon(){this.weapon=1-this.weapon;this.onEvent('weapon',{weapon:this.weapon,ammo:this.ammo[this.weapon],reserve:this.reserve[this.weapon]});}
  heal(){if(this.player.health>=100){this.onEvent('toast','VITALS ALREADY AT 100%');return;}const item=this.inventory.find(i=>i.kind==='heal'&&i.count>0);if(!item){this.onEvent('toast','NO FIELD DRESSINGS');return;}item.count--;this.player.health=Math.min(100,this.player.health+45);this.onEvent('health',this.player.health);this.onEvent('inventory',this.inventory);this.onEvent('toast','FIELD DRESSING APPLIED +45');}
  pickup(){if(!this.matchActive)return;let nearest=null,dist=2.6;for(const item of this.loot){if(!item.active)continue;const d=item.group.position.distanceTo(this.camera.position);if(d<dist){dist=d;nearest=item;}}if(!nearest){this.onEvent('toast','NO SUPPLIES IN REACH');return;}nearest.active=false;nearest.group.visible=false;const item=this.inventory.find(x=>x.name===nearest.name);if(item)item.count+=nearest.kind==='ammo'?30:1;else this.inventory.push({name:nearest.name,count:1,kind:nearest.kind});if(nearest.kind==='ammo'){if(nearest.name.includes('5.56'))this.reserve[0]+=30;else this.reserve[1]+=30;this.onEvent('ammo',{ammo:this.ammo[this.weapon],reserve:this.reserve[this.weapon],weapon:this.weapon});}this.onEvent('inventory',this.inventory);this.onEvent('toast',`SECURED: ${nearest.name}`);}
  tick(){const dt=Math.min(this.clock.getDelta(),.05);if(this.matchActive){this.matchTime+=dt;this.updatePlayer(dt);this.updateBots(dt);this.updateLoot(dt);}for(const e of this.effects){e.life-=dt;if(e.life<=0){this.scene.remove(e.mesh);e.dead=true;}}this.effects=this.effects.filter(e=>!e.dead);this.renderer.render(this.scene,this.camera);this.callbacks.forEach(f=>f(dt));}
  updatePlayer(dt){const speed=this.isCrouching?3.5:9.2;let forward=-this.move.y,right=this.move.x;if(this.keys.KeyW)forward+=1;if(this.keys.KeyS)forward-=1;if(this.keys.KeyD)right+=1;if(this.keys.KeyA)right-=1;const len=Math.hypot(forward,right);this.isMoving=len>.08;if(len>1){forward/=len;right/=len;}const dir=new THREE.Vector3(right,0,-forward).applyAxisAngle(new THREE.Vector3(0,1,0),this.yaw);const oldX=this.camera.position.x,oldZ=this.camera.position.z;this.camera.position.x+=dir.x*speed*dt;this.camera.position.z+=dir.z*speed*dt;this.camera.position.x=clamp(this.camera.position.x,-165,165);this.camera.position.z=clamp(this.camera.position.z,-165,160);for(const b of this.obstacles){if(Math.abs(this.camera.position.x-b.x)<b.w/2+.37&&Math.abs(this.camera.position.z-b.z)<b.d/2+.37){if(Math.abs(oldX-b.x)>b.w/2+.34)this.camera.position.x=oldX;if(Math.abs(oldZ-b.z)>b.d/2+.34)this.camera.position.z=oldZ;}}
    if(this.jumpVelocity!==0||!this.onGround){this.camera.position.y+=this.jumpVelocity*dt;this.jumpVelocity-=20*dt;if(this.camera.position.y<=this.groundY){this.camera.position.y=this.groundY;this.jumpVelocity=0;this.onGround=true;}}this.camera.rotation.set(this.pitch,this.yaw,0,'YXZ');if(this.weaponRoot){this.weaponRoot.position.y=-.01+(this.isMoving?Math.sin(this.matchTime*12)*.009:0);this.weaponRoot.rotation.x=this.isMoving?Math.sin(this.matchTime*6)*.008:0;}}
  jump(){if(this.onGround){this.jumpVelocity=7.1;this.onGround=false;}}
  setCrouch(v){this.isCrouching=v;this.groundY=v?1.12:1.68;}
  updateBots(dt){for(const b of this.bots){if(!b.alive)continue;b.walk+=dt;const toPlayer=this.camera.position.clone().sub(b.group.position);const distance=toPlayer.length();if(b.team==='bravo'&&distance<29){toPlayer.y=0;toPlayer.normalize();if(distance>9){b.group.position.addScaledVector(toPlayer,dt*b.speed);b.group.rotation.y=Math.atan2(toPlayer.x,toPlayer.z);}if(distance<24&&performance.now()>b.fireAt){b.fireAt=performance.now()+rand(1100,1900);if(Math.random()<.24){this.player.health=Math.max(0,this.player.health-rand(3,8));this.onEvent('health',this.player.health);this.onEvent('underFire');if(this.player.health<=0){this.player.alive=false;this.onEvent('down');}}}}
      else if(b.team==='alpha'&&distance<25){toPlayer.y=0;toPlayer.normalize();if(distance>5)b.group.position.addScaledVector(toPlayer,dt*.7);b.group.rotation.y=Math.atan2(toPlayer.x,toPlayer.z);}
      else if(b.walk>5){b.walk=0;b.goal.set(b.group.position.x+rand(-8,8),0,b.group.position.z+rand(-8,8));}else if(b.goal.distanceTo(b.group.position)>.8){const d=b.goal.clone().sub(b.group.position).setY(0).normalize();b.group.position.addScaledVector(d,dt*.45);b.group.rotation.y=Math.atan2(d.x,d.z);}
    }}
  updateLoot(dt){for(const l of this.loot)if(l.active){l.group.rotation.y+=dt*.7;l.group.position.y=.22+Math.sin(this.matchTime*2.1+l.index)*.05;}}
  mapData(){return{player:{x:this.camera.position.x,z:this.camera.position.z,yaw:this.yaw},actors:this.bots.filter(b=>b.alive).map(b=>({x:b.group.position.x,z:b.group.position.z,team:b.team})),time:this.matchTime,health:this.player.health};}
}

