import './style.css';
import { Battlefield } from './world.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const world=new Battlefield($('#world'),onGameEvent);
const shell=$('#game-shell');let activeTab='offline',paused=false,fireHeld=false,aiming=false,crouched=false,matchStartedAt=0,lastHudUpdate=0,layoutFromLobby=false,editingLayout=false;
let bots={alpha:0,bravo:0};let sensitivity=9;const controlPointers=new Map();
const saved=localStorage.getItem('fz-hud-layout');if(saved){try{const layout=JSON.parse(saved);for(const [id,p] of Object.entries(layout)){const el=document.querySelector(`[data-control="${id}"]`);if(el){el.style.left=p.x+'%';el.style.top=p.y+'%';el.style.right='auto';el.style.bottom='auto';}}}catch{}}

function switchTab(tab){activeTab=tab;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$$('.tab-panel').forEach(p=>p.classList.add('hidden'));const panel=$(`#${tab}-panel`);if(panel)panel.classList.remove('hidden');if(tab==='online')showToast('ONLINE SERVICES ARE NOT CONNECTED');}
$$('.nav-item').forEach(b=>b.addEventListener('click',()=>switchTab(b.dataset.tab)));
$('.stepper').forEach; // keep the setup controls deliberately simple and bounded
$$('.stepper').forEach(stepper=>{const team=stepper.dataset.team;const value=stepper.querySelector('b');stepper.querySelectorAll('button').forEach((btn,i)=>btn.addEventListener('click',()=>{bots[team]=Math.max(0,Math.min(8,bots[team]+(i===0?-1:1)));value.textContent=bots[team];btn.blur();}));});
$('#back-offline').addEventListener('click',()=>switchTab('offline'));
$('#sensitivity').addEventListener('input',e=>{sensitivity=Number(e.target.value);$('#sensitivity-value').textContent=sensitivity;world.setLookSensitivity(sensitivity);});world.setLookSensitivity(sensitivity);
$('#quality').addEventListener('change',e=>{const dpr=e.target.value==='performance'?1:e.target.value==='balanced'?1.3:1.65;world.renderer.setPixelRatio(Math.min(devicePixelRatio,dpr));world.resize();});
$('#fullscreen').addEventListener('click',toggleFullscreen);function toggleFullscreen(){if(!document.fullscreenElement)shell.requestFullscreen?.().catch(()=>{});else document.exitFullscreen?.();}

$('#start-match').addEventListener('click',()=>startMatch(false));
function startMatch(fromLayout=false){layoutFromLobby=fromLayout;$('#lobby').classList.add('hidden');$('#match').classList.remove('hidden');$('#pause-overlay').classList.add('hidden');$('#bag-overlay').classList.add('hidden');world.beginMatch(bots.alpha,bots.bravo);matchStartedAt=performance.now();paused=false;document.body.classList.remove('layout-edit');if(!fromLayout&&window.matchMedia('(pointer:fine)').matches){$('#world').requestPointerLock?.();}updateInventory(world.inventory);updateAmmo({ammo:world.ammo[0],reserve:world.reserve[0],weapon:0});updateTeamHud();showToast(bots.alpha+ bots.bravo?`FIELD LIVE · ${bots.alpha+bots.bravo} SPARRING OPERATORS`:'FIELD LIVE · QUIET SANDBOX');}
function returnToLobby(){paused=false;editingLayout=false;world.endMatch();$('#pause-overlay').classList.add('hidden');$('#bag-overlay').classList.add('hidden');$('#match').classList.add('hidden');$('#lobby').classList.remove('hidden');$('#layout-hint').classList.add('hidden');document.body.classList.remove('layout-edit');world.camera.position.set(65,20,54);world.camera.lookAt(0,4,-24);world.weaponRoot.visible=false;}
$('#pause-button').addEventListener('click',pauseMatch);function pauseMatch(){if(!world.matchActive)return;paused=true;fireHeld=false;document.exitPointerLock?.();$('#pause-overlay').classList.remove('hidden');}
$('#resume-button').addEventListener('click',()=>{paused=false;$('#pause-overlay').classList.add('hidden');if(window.matchMedia('(pointer:fine)').matches)$('#world').requestPointerLock?.();});
$('#lobby-button').addEventListener('click',returnToLobby);
$('#bag-overlay').addEventListener('click',e=>{if(e.target===$('#bag-overlay'))$('#bag-overlay').classList.add('hidden');});$('#close-bag').addEventListener('click',()=>$('#bag-overlay').classList.add('hidden'));
$$('.weapon-slot').forEach(slot=>slot.addEventListener('click',()=>{world.weapon=Number(slot.dataset.slot);updateWeapon();}));
function openBag(){if(paused||editingLayout)return;$('#bag-overlay').classList.remove('hidden');updateInventory(world.inventory);document.exitPointerLock?.();}
function toggleBag(){if(!$('#bag-overlay').classList.contains('hidden'))$('#bag-overlay').classList.add('hidden');else openBag();}

function updateAmmo(data){const index=data.weapon??world.weapon;$('#ammo-count').innerHTML=`${data.ammo} <i>/ ${data.reserve}</i>`;$('#weapon-name').textContent=index===0?'AR-17 // 5.56MM':'VX-9 // 9MM';$('.weapon-type').textContent=index===0?'ASSAULT RIFLE':'COMPACT SMG';$('.ammo-bar b').style.width=`${Math.max(0,data.ammo/world.maxAmmo[index]*100)}%`;const bag=$(`#bag-ammo-${index}`);if(bag)bag.textContent=`${data.ammo} / ${data.reserve}`;}
function updateWeapon(){world.weaponRoot.visible=true;$$('.weapon-slot').forEach(s=>s.classList.toggle('active',Number(s.dataset.slot)===world.weapon));updateAmmo({ammo:world.ammo[world.weapon],reserve:world.reserve[world.weapon],weapon:world.weapon});}
function updateHealth(value){$('#health-value').textContent=Math.round(value);$('#health-fill').style.width=value+'%';$('#squad-health-self').textContent=Math.round(value);$('#health-fill').style.background=value<30?'#cf755f':'#a9c779';}
function updateInventory(items){$('#inventory-list').innerHTML=items.map(i=>`<div class="inventory-item"><b>${escapeHtml(i.name)}</b><span>×${i.count}</span></div>`).join('');$('#item-count').textContent=`${items.reduce((n,i)=>n+i.count,0)} ITEMS`;}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function updateTeamHud(){const container=$('#squad-bots');container.innerHTML=world.bots.filter(b=>b.team==='alpha').map((b,i)=>`<div class="bot-squad-row"><i class="squad-dot ally"></i><span>ALPHA-0${i+2}</span><b>100</b></div>`).join('');$('#alive-count').textContent=`OPERATORS ${String(world.bots.filter(b=>b.alive).length+1).padStart(2,'0')}`;}
function showToast(message){const el=$('#toast');el.textContent=message;el.classList.remove('hidden');clearTimeout(showToast.timeout);showToast.timeout=setTimeout(()=>el.classList.add('hidden'),1800);}
function addFeed(text){const feed=$('#kill-feed'),line=document.createElement('div');line.className='kill-line';line.textContent=text;feed.prepend(line);while(feed.children.length>3)feed.lastChild.remove();setTimeout(()=>line.remove(),4300);}

function onGameEvent(type,data){switch(type){case'matchStart':updateTeamHud();break;case'ammo':updateAmmo(data);break;case'weapon':updateWeapon();showToast(data.weapon===0?'AR-17 RANGER':'VX-9 VECTOR');break;case'health':updateHealth(data);break;case'inventory':updateInventory(data);break;case'toast':showToast(data);break;case'hitmarker':$('.crosshair').classList.add('hit');setTimeout(()=>$('.crosshair').classList.remove('hit'),100);break;case'hit':break;case'kill':addFeed(data.team==='bravo'?'YOU  ▸  HOSTILE OPERATOR':'YOU  ▸  FRIENDLY FIRE');updateTeamHud();break;case'underFire':shell.classList.add('under-fire');setTimeout(()=>shell.classList.remove('under-fire'),180);break;case'down':paused=true;showToast('OPERATOR DOWN · RETURN TO LOBBY');setTimeout(()=>{$('#pause-overlay').classList.remove('hidden');},650);break;}}

// Desktop look, fire and movement. Pointer lock is optional; unlocked drag still turns the camera.
window.addEventListener('keydown',e=>{if(['Space','Tab','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();world.keys[e.code]=true;if(e.repeat)return;switch(e.code){case'Escape':if(!$('#bag-overlay').classList.contains('hidden'))$('#bag-overlay').classList.add('hidden');else if(world.matchActive&&!paused)pauseMatch();else if(paused){paused=false;$('#pause-overlay').classList.add('hidden');}break;case'Space':if(world.matchActive)world.jump();break;case'KeyC':if(world.matchActive){crouched=!crouched;world.setCrouch(crouched);$('#match').classList.toggle('crouching',crouched);}break;case'KeyR':world.reload();break;case'KeyF':world.pickup();break;case'KeyH':world.heal();break;case'Tab':toggleBag();break;case'Digit1':world.weapon=0;updateWeapon();break;case'Digit2':world.weapon=1;updateWeapon();break;case'KeyE':world.pickup();break;}});
window.addEventListener('keyup',e=>{world.keys[e.code]=false;if(e.code==='ShiftLeft'||e.code==='ShiftRight')world.keys[e.code]=false;});
window.addEventListener('mousemove',e=>{if(document.pointerLockElement===$('#world'))world.look(e.movementX,e.movementY);});
$('#world').addEventListener('mousedown',e=>{if(e.button===0&&world.matchActive&&!paused&&!editingLayout){fireHeld=true;if(document.pointerLockElement!==$('#world'))$('#world').requestPointerLock?.();}if(e.button===2&&world.matchActive){aiming=true;setAim(true);}});window.addEventListener('mouseup',e=>{if(e.button===0)fireHeld=false;if(e.button===2){aiming=false;setAim(false);}});$('#world').addEventListener('contextmenu',e=>e.preventDefault());

function setAim(v){aiming=v;world.isAiming=v;world.camera.fov=v?47:73;world.camera.updateProjectionMatrix();$('#aim-btn').classList.toggle('active',v);}
function handleControl(name,down){if(name==='move')return;if(name==='fire'){fireHeld=down;return;}if(name==='aim'){setAim(down);return;}if(!down)return;switch(name){case'jump':world.jump();break;case'crouch':crouched=!crouched;world.setCrouch(crouched);$('#match').classList.toggle('crouching',crouched);$('#crouch').classList.toggle('active',crouched);break;case'heal':world.heal();break;case'swap':world.swapWeapon();break;case'bag':toggleBag();break;case'reload':world.reload();break;}}
const movePad=$('#move-pad'),knob=$('#move-knob');
movePad.addEventListener('pointerdown',e=>{if(editingLayout)return;e.preventDefault();movePad.setPointerCapture(e.pointerId);controlPointers.set(e.pointerId,'move');moveFromEvent(e);});
movePad.addEventListener('pointermove',e=>{if(controlPointers.get(e.pointerId)==='move')moveFromEvent(e);});
function moveFromEvent(e){const r=$('.pad-ring').getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=r.width*.34,len=Math.hypot(dx,dy),scale=len>max?max/len:1;const x=dx*scale,y=dy*scale;knob.style.transform=`translate(calc(-50% + ${x}px),calc(-50% + ${y}px))`;world.move={x:x/max,y:y/max};}
function stopPointer(e){const name=controlPointers.get(e.pointerId);if(name){controlPointers.delete(e.pointerId);if(name==='move'){world.move={x:0,y:0};knob.style.transform='translate(-50%,-50%)';}else handleControl(name,false);}}
