<!DOCTYPE html>
<html><head><script type="module" src="/@vite/client"></script>

<meta charset="utf-8">
<title>FIELD ZERO smoke test</title>
</head><body><iframe id="app" src="/" allow="fullscreen"></iframe>
<pre id="result">PASS app mounted with WebGL canvas
PASS bot counts start at zero
PASS alpha bot count capped at eight
PASS alpha bot count floors at zero
PASS team bot counts independent
PASS settings tab opens
PASS match starts and lobby hides
PASS initial weapon and HUD shown
PASS weapon selection updates HUD
PASS crouch toggles presentation
PASS pause opens
PASS resume clears overlay
PASS backpack opens by keyboard
PASS backpack closes
PASS HUD editor opens from pause
PASS HUD layout saves locally and returns to pause
PASS HUD layout reset removes saved arrangement
PASS return to lobby
PASS HUD editor opens from lobby
PASS lobby HUD editor returns to lobby
PASS simultaneous touch movement, aim, and fire register
PASS touch fire consumes ammunition
PASS reload refills the selected magazine
FAIL fullscreen can be entered from lobby</pre>
<script>
const frame = document.querySelector('#app');
const result = document.querySelector('#result');
const errors = [];
frame.addEventListener('load', async () => {
  const w = frame.contentWindow;
  w.addEventListener('error', e => errors.push(`${e.message} @ ${e.filename}:${e.lineno}`));
  await new Promise(resolve => setTimeout(resolve, 600));
  const d = frame.contentDocument;
  const out = [];
  const check = (name, ok) => out.push(`${ok ? 'PASS' : 'FAIL'} ${name}`);
  const click = selector => {
    const el = d.querySelector(selector);
    if (!el) throw new Error(`Missing selector ${selector}`);
    el.click();
  };
  const key = (type, code) => w.dispatchEvent(new w.KeyboardEvent(type, {code, bubbles:true}));
  const wait = ms => new Promise(resolve => setTimeout(resolve, ms));
  const touch = (el, type, pointerId, x, y) => {
    el.setPointerCapture = () => {};
    el.dispatchEvent(new w.PointerEvent(type, {pointerId, pointerType:'touch', isPrimary:pointerId===1, clientX:x, clientY:y, bubbles:true, cancelable:true}));
  };
  try {
    check('app mounted with WebGL canvas', !!d.querySelector('canvas#world'));
    const alpha = d.querySelector('[data-team="alpha"]');
    const bravo = d.querySelector('[data-team="bravo"]');
    check('bot counts start at zero', alpha.querySelector('b').textContent === '0' && bravo.querySelector('b').textContent === '0');
    for (let i=0; i<9; i++) alpha.querySelectorAll('button')[1].click();
    check('alpha bot count capped at eight', alpha.querySelector('b').textContent === '8');
    for (let i=0; i<9; i++) alpha.querySelectorAll('button')[0].click();
    check('alpha bot count floors at zero', alpha.querySelector('b').textContent === '0');
    alpha.querySelectorAll('button')[1].click();
    bravo.querySelectorAll('button')[1].click();
    check('team bot counts independent', alpha.querySelector('b').textContent === '1' && bravo.querySelector('b').textContent === '1');
    click('[data-tab="settings"]');
    check('settings tab opens', !d.querySelector('#settings-panel').classList.contains('hidden'));
    click('[data-tab="offline"]');
    click('#start-match');
    check('match starts and lobby hides', !d.querySelector('#match').classList.contains('hidden') && d.querySelector('#lobby').classList.contains('hidden'));
    check('initial weapon and HUD shown', d.querySelector('#weapon-name').textContent.includes('AR-17') && !!d.querySelector('#minimap'));
    key('keydown', 'Digit2');
    check('weapon selection updates HUD', d.querySelector('#weapon-name').textContent.includes('VX-9'));
    key('keydown', 'Digit1');
    key('keydown', 'KeyC');
    check('crouch toggles presentation', d.querySelector('#match').classList.contains('crouching'));
    key('keydown', 'KeyC');
    click('#pause-button');
    check('pause opens', !d.querySelector('#pause-overlay').classList.contains('hidden'));
    click('#resume-button');
    check('resume clears overlay', d.querySelector('#pause-overlay').classList.contains('hidden'));
    key('keydown', 'Tab');
    check('backpack opens by keyboard', !d.querySelector('#bag-overlay').classList.contains('hidden'));
    click('#close-bag');
    check('backpack closes', d.querySelector('#bag-overlay').classList.contains('hidden'));
    click('#pause-button');
    click('#pause-layout');
    check('HUD editor opens from pause', !d.querySelector('#layout-hint').classList.contains('hidden'));
    click('#save-layout');
    check('HUD layout saves locally and returns to pause', !!w.localStorage.getItem('fz-hud-layout') && !d.querySelector('#pause-overlay').classList.contains('hidden'));
    click('#pause-layout');
    click('#reset-layout');
    check('HUD layout reset removes saved arrangement', !w.localStorage.getItem('fz-hud-layout'));
    click('#resume-button');
    click('#pause-button');
    click('#lobby-button');
    check('return to lobby', !d.querySelector('#lobby').classList.contains('hidden') && d.querySelector('#match').classList.contains('hidden'));
    click('[data-tab="layout"]');
    click('#edit-layout');
    check('HUD editor opens from lobby', !d.querySelector('#layout-hint').classList.contains('hidden') && !d.querySelector('#match').classList.contains('hidden'));
    click('#save-layout');
    check('lobby HUD editor returns to lobby', !d.querySelector('#lobby').classList.contains('hidden') && d.querySelector('#match').classList.contains('hidden'));
    click('#start-match');
    const move = d.querySelector('#move-pad'), aim = d.querySelector('#aim-btn'), fire = d.querySelector('#fire-btn');
    touch(move, 'pointerdown', 11, 120, 450);
    touch(aim, 'pointerdown', 12, 700, 450);
    touch(fire, 'pointerdown', 13, 760, 500);
    touch(move, 'pointermove', 11, 155, 470);
    await wait(350);
    check('simultaneous touch movement, aim, and fire register', aim.classList.contains('active') && fire.classList.contains('active') && !d.querySelector('#move-knob').style.transform.includes('0px'));
    check('touch fire consumes ammunition', Number(d.querySelector('#ammo-count').textContent.trim().split(' ')[0]) < 30);
    touch(fire, 'pointerup', 13, 760, 500);
    touch(aim, 'pointerup', 12, 700, 450);
    touch(move, 'pointerup', 11, 155, 470);
    key('keydown', 'KeyR');
    await wait(1550);
    check('reload refills the selected magazine', d.querySelector('#ammo-count').textContent.trim().startsWith('30 '));
    key('keyup', 'KeyR');
    click('#pause-button');
    click('#lobby-button');
    click('#fullscreen');
    await wait(250);
    const fullscreenWorked = !!d.fullscreenElement;
    if (fullscreenWorked) d.exitFullscreen();
    check('fullscreen can be entered from lobby', fullscreenWorked);
    w.localStorage.removeItem('fz-hud-layout');
    result.textContent = [...out, ...errors.map(e => `JS ERROR ${e}`)].join('\n');
  } catch (e) {
    result.textContent = `ERROR ${e.stack}\n${[...out, ...errors].join('\n')}`;
  }
});
</script>
</body></html>

