const pages = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const page = pages.find(x => x.type === 'page' && x.url === 'http://127.0.0.1:5173/');
if (!page) throw new Error('game page target missing');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, {once:true}); ws.addEventListener('error', reject, {once:true}); });
let id=0; const pending=new Map(); ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(new Error(m.error.message)):p.resolve(m.result)}});
const cdp=(method,params={})=>new Promise((resolve,reject)=>{const n=++id;pending.set(n,{resolve,reject});ws.send(JSON.stringify({id:n,method,params}))});
const ev=async expression=>(await cdp('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true})).result.value;
await cdp('Runtime.enable'); await cdp('Page.enable'); await new Promise(r=>setTimeout(r,500));
console.log('test hook',await ev('!!window.__fieldZeroTestWorld'));
const result=await ev(`(()=>{const w=window.__fieldZeroTestWorld;if(!w)throw new Error('test hook missing');document.querySelector('#start-match').click();const item=w.loot.find(x=>x.active);const before=w.inventory.reduce((n,x)=>n+x.count,0);w.camera.position.set(item.group.position.x,1.68,item.group.position.z);window.dispatchEvent(new KeyboardEvent('keydown',{code:'KeyF',bubbles:true}));return {item:item.name,active:item.active,before,after:w.inventory.reduce((n,x)=>n+x.count,0),toast:document.querySelector('#toast').textContent,inventory:document.querySelector('#inventory-list').innerText}})()`);
console.log(JSON.stringify(result,null,2));
ws.close();
EOF

